// And groups predicates with the AND operator between them.
func And(predicates ...predicate.LotteryDraw) predicate.LotteryDraw {
	return predicate.LotteryDraw(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.LotteryDraw) predicate.LotteryDraw {
	return predicate.LotteryDraw(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.LotteryDraw) predicate.LotteryDraw {
	return predicate.LotteryDraw(sql.NotPredicates(p))
}
